function s(t){if(t==null||t==="")return"";if(Array.isArray(t)&&t.length>=3){const[r,n,i]=t;return`${r}-${String(n).padStart(2,"0")}-${String(i).padStart(2,"0")}`}if(t instanceof Date&&!Number.isNaN(t.getTime())){const r=t.getFullYear(),n=String(t.getMonth()+1).padStart(2,"0"),i=String(t.getDate()).padStart(2,"0");return`${r}-${n}-${i}`}if(typeof t=="string"){const r=t.match(/^(\d{4}-\d{2}-\d{2})/);if(r)return r[1];const n=Date.parse(t);if(!Number.isNaN(n))return s(new Date(n))}return""}function f(t){if(t==null||t==="")return"";if(typeof t=="string"){const e=t.match(/^(\d{4}-\d{2}-\d{2})[T\s](\d{2}:\d{2})/);if(e)return`${e[1]} ${e[2]}`}const r=t instanceof Date?t:new Date(t);if(Number.isNaN(r.getTime()))return s(t);const n=s(r),i=String(r.getHours()).padStart(2,"0"),o=String(r.getMinutes()).padStart(2,"0");return`${n} ${i}:${o}`}export{f};
